import numpy as np
from scipy.ndimage import label,find_objects
p=np.load('source_pixels.npz')['rgb'].astype(int)
# Find saturated blue components each frame; inspect largest components near x<180
for t in [0,10,20,25,30,35,40,45,48,50,60,95]:
 f=p[t];r,g,b=f.transpose(2,0,1)
 for th in [(b-r>25)&(b-g>10)&(b>80)]:
  l,n=label(th); comps=[]
  for i,sl in enumerate(find_objects(l),1):
   if sl:
    yy,xx=sl; area=(l[sl]==i).sum()
    if area>=20: comps.append((area,(xx.start,yy.start,xx.stop-1,yy.stop-1)))
  comps.sort(reverse=True)
  print(t,comps[:10])
PY"
